import { Meta, StoryObj } from "@storybook/react";
import { SegmentedControls } from "./segmented-controls";
import { ComponentProps, useState } from "react";
import { action } from "storybook/actions";
import { expect, fn, userEvent, within } from "storybook/test";
import { ShowcaseLayout, Variant, showcaseParameters } from "@/storybook/preview";

// The component is fully controlled, so stories wrap it in local state to stay interactive.
const InteractiveSegmentedControls = (props: ComponentProps<typeof SegmentedControls>) => {
  const [value, setValue] = useState(props.selectedValue);
  return (
    <SegmentedControls
      {...props}
      selectedValue={value}
      onChange={(value: string, name: string) => {
        setValue(value);
        action("onChange")(value, name);
      }}
    />
  );
};

const meta = {
  title: "Primitives/Segmented Controls",
  component: SegmentedControls,
  parameters: {
    docs: {
      description: {
        component:
          "Radio group styled as connected segments, with an animated marker that slides to the " +
          "selected segment. The selection is fully controlled: the component reports choices via " +
          "`onChange` and renders whatever `selectedValue` says.",
      },
    },
  },
  render: (args) => <InteractiveSegmentedControls {...args} />,
  argTypes: {
    "data-testid": { table: { disable: true } },
  },
  args: {
    dateKey: "someKey",
    name: "my-name",
    segments: [
      { label: "First", value: "first" },
      { label: "Second", value: "second" },
    ],
    selectedValue: "first",
    onChange: fn(),
  },
} satisfies Meta<typeof SegmentedControls>;

export default meta;

type Story = StoryObj<typeof meta>;

export const Default: Story = {};

export const VariantSegments: Story = {
  parameters: showcaseParameters,
  render: (args) => (
    <ShowcaseLayout title="segments" variantType="prop">
      <Variant label="two segments">
        <InteractiveSegmentedControls {...args} name="two-segments" />
      </Variant>
      <Variant label="three segments">
        <InteractiveSegmentedControls
          {...args}
          name="three-segments"
          segments={[
            { label: "Per person", value: "perPerson" },
            { label: "Totalt", value: "total" },
            { label: "Per dag", value: "perDay" },
          ]}
          selectedValue="total"
        />
      </Variant>
    </ShowcaseLayout>
  ),
};

const onChangeSpy = fn();

export const TestSelectSegment: Story = {
  render: function Renderer(args) {
    const [value, setValue] = useState(args.selectedValue);
    return (
      <SegmentedControls
        {...args}
        selectedValue={value}
        onChange={(value: string, name: string) => {
          onChangeSpy(value, name);
          setValue(value);
        }}
      />
    );
  },
  play: async ({ canvasElement }) => {
    onChangeSpy.mockClear();
    const canvas = within(canvasElement);
    await userEvent.click(canvas.getByText("Second"));
    await expect(onChangeSpy).toHaveBeenCalledWith("second", "my-name");
    await expect(canvas.getByRole("radio", { name: "Second" })).toBeChecked();
  },
};
