import styles from "./segmented-controls.module.less";
import { motion } from "framer-motion";
import { multipleClassNames } from "@/core/helpers";

type Segment<ValueType extends string> = {
  label: string;
  value: ValueType;
  contentfulLabelId?: string;
};

type SegmentedControlsProps<ValueType extends string> = {
  /** Radio group name, must be unique per rendered instance */
  name: string;
  /** Extra key for the selection marker's layoutId, keeps instances from animating between each other */
  dateKey: string;
  segments: Array<Segment<ValueType>>;
  /** Controlled selection. Update this from `onChange` */
  selectedValue: ValueType;
  className?: string;
  onChange: (value: ValueType, name: string) => void;
  "data-testid"?: string;
};

export const SegmentedControls = <ValueType extends string>({
  className,
  name,
  dateKey,
  segments,
  selectedValue,
  onChange,
  "data-testid": dataTestId,
}: SegmentedControlsProps<ValueType>) => {
  return (
    <motion.div layout layoutRoot className={multipleClassNames(className, styles.wrapper)} data-testid={dataTestId}>
      {segments.map((segment) => {
        const selected = segment.value === selectedValue;
        return (
          <div key={segment.value} className={styles.radioWrapper}>
            <input
              className={styles.radioInput}
              type="radio"
              id={segment.value + "-" + name}
              name={name}
              checked={selected}
              onChange={() => onChange(segment.value, name)}
            />
            {selected && (
              <motion.div layout layoutId={"selected-for-" + name + dateKey} className={styles.selectedMarker} />
            )}
            <label
              tabIndex={0}
              className={multipleClassNames(styles.radioLabel, selected && styles.selected)}
              htmlFor={segment.value + "-" + name}
              data-contentful-label-id={segment.contentfulLabelId}
              data-testid={`segmented-control-${name}-${segment.value}`}
            >
              {segment.label}
            </label>
          </div>
        );
      })}
    </motion.div>
  );
};
